    run_test(&format!("{left}r#''#{right} | get 0"), "")?;
    run_test(
        &format!(r#"{left}r#'a string with sharp inside # and ends with #'#{right} | get 0"#),
        "a string with sharp inside # and ends with #",
    )
}

